#ifndef WEBSERVER_INCLUDE_WEBSERVER_RESOURCE_REGISTRY_
#define WEBSERVER_INCLUDE_WEBSERVER_RESOURCE_REGISTRY_

#include <cstdint>
#include <span>
#include <string_view>

namespace webserver {

// One static file embedded into the firmware (generated by the web UI build,
// see webserver/README.md). All views are NUL-terminated literals.
struct WebResource {
  std::string_view path;              // e.g. "/index.html"; "/" too
  std::string_view content_type;
  std::string_view content_encoding;  // "gzip" or empty
  std::string_view cache_control;
  std::span<const std::uint8_t> data;
};

class ResourceRegistry {
 public:
  explicit ResourceRegistry(std::span<const WebResource> resources) noexcept
      : resources_(resources) {}

  // nullptr if there is no such file.
  const WebResource* Find(std::string_view path) const noexcept;

 private:
  std::span<const WebResource> resources_;
};

}  // namespace webserver

#endif  // WEBSERVER_INCLUDE_WEBSERVER_RESOURCE_REGISTRY_
